result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/columnize.py", "content": "#!/usr/bin/env python3
"""Columnize: align whitespace-separated rows like `column -t`.

Reads rows from stdin, splits each row into cells (whitespace by default,
or a custom delimiter via -s SEP), and prints the rows with every cell in
a column left-justified to that column's widest value, separated by two
spaces. Columns listed in -R LIST are right-justified instead.
"""

import argparse
import sys


def main() -> None:
    parser = argparse.ArgumentParser(description="Align columns of text.")
    parser.add_argument(
        "-s",
        metavar="SEP",
        default=None,
        help="input delimiter (default: split on whitespace runs)",
    )
    parser.add_argument(
        "-R",
        metavar="LIST",
        default="",
        help="comma-separated 1-based column numbers to right-align",
    )
    args = parser.parse_args()

    right_cols = set()
    if args.R:
        for part in args.R.split(","):
            part = part.strip()
            if not part:
                continue
            try:
                right_cols.add(int(part))
            except ValueError:
                parser.error(f"invalid column number in -R LIST: {part!r}")

    def split_row(line: str) -> list[str]:
        line = line.rstrip("\n")
        if args.s is None:
            return line.split()
        return line.split(args.s)

    rows = [split_row(line) for line in sys.stdin]

    # Drop a trailing empty row produced by input ending in a newline.
    while rows and not rows[-1]:
        rows.pop()

    if not rows:
        return

    ncols = max(len(row) for row in rows)
    widths = [0] * ncols
    for row in rows:
        for i, cell in enumerate(row):
            widths[i] = max(widths[i], len(cell))

    out_lines = []
    for row in rows:
        parts = []
        for i in range(ncols):
            cell = row[i] if i < len(row) else ""
            width = widths[i]
            if i + 1 < ncols:
                width = max(width, len(" ".join([])))  # keep at least separator room
                width = max(widths[i], 1)
            if i == ncols - 1:
                # Last column: no padding needed unless right-aligned.
                if i + 1 in right_cols:
                    parts.append(cell.rjust(widths[i]))
                else:
                    parts.append(cell)
            elif i + 1 in right_cols:
                parts.append(cell.rjust(width))
            else:
                parts.append(cell.ljust(width))
        out_lines.append("  ".join(parts).rstrip())

    print("\n".join(out_lines))


if __name__ == "__main__":
    main()
"})
